    const path = join(mkdtempSync(join(tmpdir(), "todo-")), "todos.json");
    writeFileSync(path, JSON.stringify([{ id: 2, title: "eggs", done: true }]));
    expect(load(path)).toEqual([{ id: 2, title: "eggs", completed: true }]);
  });
});

